    psx_cyc_step(cpu, 0x1u);
#endif
    /* nop */  /* 0x8005F794: 0x00000000 */
#ifdef PSX_COSIM
    cosim_instr(0x8005F794u);
#endif
    if (!psx_game_text_native_ok(0x8005F798u)) { cpu->pc = 0x8005F798u; return; }  /* stale-static guard */
    func_8005F798(cpu); return;  /* fallthrough to split piece */
    if (!psx_game_text_native_ok(0x8005F798u)) { cpu->pc = 0x8005F798u; return; }  /* stale-static guard */
    func_8005F798(cpu);  /* fallthrough to next function */
